document.addEventListener('DOMContentLoaded', () => {

  // Counter button
  const counterBtn = document.getElementById('counter-btn');
  let count = 0;
  counterBtn.addEventListener('click', () => {
    count++;
    counterBtn.textContent = `Clicked: ${count} time${count !== 1 ? 's' : ''}`;
  });

  // Toggle button
  const toggleBtn = document.getElementById('toggle-btn');
  let active = false;
  toggleBtn.addEventListener('click', () => {
    active = !active;
    toggleBtn.textContent = active ? 'Deactivate' : 'Activate';
    toggleBtn.classList.toggle('btn-active', active);
  });

  // Loading button
  const loadingBtn = document.getElementById('loading-btn');
  loadingBtn.addEventListener('click', () => {
    if (loadingBtn.classList.contains('btn-loading')) return;
    const originalText = loadingBtn.textContent;
    loadingBtn.classList.add('btn-loading');
    loadingBtn.innerHTML = '<span class="spinner"></span> Processing...';
    setTimeout(() => {
      loadingBtn.classList.remove('btn-loading');
      loadingBtn.textContent = 'Done!';
      setTimeout(() => {
        loadingBtn.textContent = originalText;
      }, 1500);
    }, 2000);
  });

  // Ripple button
  const rippleBtn = document.getElementById('ripple-btn');
  rippleBtn.addEventListener('click', (e) => {
    const rect = rippleBtn.getBoundingClientRect();
    const size = Math.max(rect.width, rect.height);
    const x = e.clientX - rect.left - size / 2;
    const y = e.clientY - rect.top - size / 2;

    const ripple = document.createElement('span');
    ripple.classList.add('ripple-circle');
    ripple.style.width = ripple.style.height = size + 'px';
    ripple.style.left = x + 'px';
    ripple.style.top = y + 'px';

    rippleBtn.appendChild(ripple);

    ripple.addEventListener('animationend', () => {
      ripple.remove();
    });
  });

  // Button group
  const btnGroup = document.getElementById('btn-group');
  const groupItems = btnGroup.querySelectorAll('.btn-group-item');
  groupItems.forEach(item => {
    item.addEventListener('click', () => {
      groupItems.forEach(i => i.classList.remove('active'));
      item.classList.add('active');
    });
  });

});

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --blue-50: #f5f5f5;
  --blue-100: #e5e5e5;
  --blue-200: #d4d4d4;
  --blue-400: #a3a3a3;
  --blue-500: #ffffff;
  --blue-600: #ffffff;
  --blue-700: #e5e5e5;
  --blue-800: #d4d4d4;
  --blue-900: #a3a3a3;
  --white: #000000;
  --gray-50: #0a0a0a;
  --gray-100: #111111;
  --gray-200: #222222;
  --gray-300: #333333;
  --gray-600: #a3a3a3;
  --gray-900: #f5f5f5;
  --radius: 8px;
  --radius-lg: 12px;
  --shadow: 0 1px 3px rgba(0,0,0,0.3), 0 1px 2px rgba(0,0,0,0.2);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.3), 0 2px 4px -2px rgba(0,0,0,0.2);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.3), 0 4px 6px -4px rgba(0,0,0,0.2);
  --transition: 0.2s ease;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.65;
  color: var(--gray-900);
  background: #000000;
  -webkit-font-smoothing: antialiased;
}

h1 {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1.1;
  color: #ffffff;
}

h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.15;
  margin-bottom: 16px;
  color: #ffffff;
}

h3 {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
  color: #ffffff;
}

a {
  color: #ffffff;
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: #cccccc;
}

/* Nav */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  height: 64px;
  background: rgba(0,0,0,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid #222222;
}

.nav-inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  font-size: 1.25rem;
  font-weight: 800;
  color: #ffffff;
  letter-spacing: -0.03em;
}

.logo:hover {
  color: #cccccc;
}

.nav-links {
  display: flex;
  gap: 32px;
}

.nav-links a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: #a3a3a3;
  min-height: 44px;
  display: flex;
  align-items: center;
}

.nav-links a:hover {
  color: #ffffff;
}

/* Sections */
.section {
  max-width: 1100px;
  margin: 0 auto;
  padding: 96px 24px;
}

.section-alt {
  max-width: 100%;
  background: #0a0a0a;
}

.section-alt > * {
  max-width: 1100px;
  margin-left: auto;
  margin-right: auto;
}

.section-alt > .card-grid {
  max-width: 1100px;
}

.section-desc {
  font-size: 1.125rem;
  color: #a3a3a3;
  max-width: 600px;
  margin-bottom: 48px;
}

.section-alt .section-desc {
  margin-left: auto;
  margin-right: auto;
}

/* Hero */
.hero {
  max-width: 1100px;
  margin: 0 auto;
  padding: 120px 24px 96px;
  text-align: center;
}

.hero p {
  font-size: 1.25rem;
  color: #a3a3a3;
  max-width: 560px;
  margin: 24px auto 40px;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 10px 24px;
  font-family: inherit;
  font-size: 0.9375rem;
  font-weight: 600;
  line-height: 1;
  border: 2px solid transparent;
  border-radius: var(--radius);
  cursor: pointer;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
  white-space: nowrap;
  user-select: none;
  -webkit-user-select: none;
}

.btn:focus-visible {
  outline: 2px solid #ffffff;
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

/* Primary (White bg, Black text) */
.btn-primary {
  background: #ffffff;
  color: #000000;
  border-color: #ffffff;
}

.btn-primary:hover {
  background: #e5e5e5;
  border-color: #e5e5e5;
}

.btn-primary:active {
  background: #d4d4d4;
  border-color: #d4d4d4;
}

/* Gradient */
.btn-gradient {
  background: linear-gradient(135deg, #ffffff, #cccccc);
  color: #000000;
  border-color: transparent;
}

.btn-gradient:hover {
  background: linear-gradient(135deg, #e5e5e5, #b3b3b3);
}

/* Outline */
.btn-outline {
  background: transparent;
  color: #ffffff;
  border-color: #ffffff;
}

.btn-outline:hover {
  background: #ffffff;
  color: #000000;
}

/* Shadow */
.btn-shadow {
  box-shadow: 0 4px 14px rgba(255, 255, 255, 0.25);
}

.btn-shadow:hover {
  box-shadow: 0 6px 20px rgba(255, 255, 255, 0.35);
}

/* Pill */
.btn-pill {
  border-radius: 999px;
}

/* Sizes */
.btn-sm {
  min-height: 36px;
  padding: 6px 16px;
  font-size: 0.8125rem;
}

.btn-lg {
  min-height: 52px;
  padding: 14px 32px;
  font-size: 1.0625rem;
}

/* Icon button */
.btn-icon svg {
  flex-shrink: 0;
}

/* White button (for CTA section) */
.btn-white {
  background: #000000;
  color: #ffffff;
  border-color: #000000;
}

.btn-white:hover {
  background: #1a1a1a;
  border-color: #1a1a1a;
}

.btn-white-outline {
  background: transparent;
  color: #000000;
  border-color: rgba(0,0,0,0.5);
}

.btn-white-outline:hover {
  background: #000000;
  color: #ffffff;
  border-color: #000000;
}

/* Loading state */
.btn-loading {
  pointer-events: none;
  opacity: 0.85;
}

.btn-loading .spinner {
  width: 18px;
  height: 18px;
  border: 2px solid rgba(0,0,0,0.2);
  border-top-color: #000000;
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Ripple */
.btn-ripple {
  position: relative;
  overflow: hidden;
}

.ripple-circle {
  position: absolute;
  border-radius: 50%;
  background: rgba(0,0,0,0.25);
  transform: scale(0);
  animation: ripple-anim 0.6s ease-out;
  pointer-events: none;
}

@keyframes ripple-anim {
  to {
    transform: scale(4);
    opacity: 0;
  }
}

/* Active toggle */
.btn-active {
  background: #a3a3a3;
  border-color: #a3a3a3;
  color: #000000;
  box-shadow: inset 0 2px 4px rgba(0,0,0,0.2);
}

/* Button Group */
.btn-group {
  display: inline-flex;
  border-radius: var(--radius);
  overflow: hidden;
  border: 2px solid #ffffff;
  flex-wrap: wrap;
}

.btn-group-item {
  background: #000000;
  color: #ffffff;
  border: none;
  border-radius: 0;
  border-right: 1px solid #333333;
  min-height: 44px;
  padding: 10px 24px;
  font-weight: 600;
}

.btn-group-item:last-child {
  border-right: none;
}

.btn-group-item:hover {
  background: #1a1a1a;
}

.btn-group-item.active {
  background: #ffffff;
  color: #000000;
}

.btn-group-item:active {
  transform: none;
}

/* Cards */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 24px;
}

.card {
  background: #111111;
  border: 1px solid #222222;
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow);
}

.section-alt .card {
  background: #111111;
}

.card p {
  color: #a3a3a3;
  margin-bottom: 24px;
}

.button-row {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

/* CTA Section */
.section-cta {
  background: linear-gradient(135deg, #1a1a1a, #000000);
  color: #ffffff;
  text-align: center;
  max-width: 100%;
  padding: 96px 24px;
  border-top: 1px solid #222222;
  border-bottom: 1px solid #222222;
}

.section-cta h2 {
  color: #ffffff;
}

.section-cta p {
  color: #a3a3a3;
  font-size: 1.125rem;
  max-width: 500px;
  margin: 0 auto 40px;
}

.section-cta .btn-white {
  background: #ffffff;
  color: #000000;
  border-color: #ffffff;
}

.section-cta .btn-white:hover {
  background: #e5e5e5;
  border-color: #e5e5e5;
}

.section-cta .btn-white-outline {
  background: transparent;
  color: #ffffff;
  border-color: rgba(255,255,255,0.5);
}

.section-cta .btn-white-outline:hover {
  background: #ffffff;
  color: #000000;
  border-color: #ffffff;
}

/* Footer */
.footer {
  border-top: 1px solid #222222;
  padding: 32px 24px;
  text-align: center;
  background: #000000;
}

.footer-inner {
  max-width: 1100px;
  margin: 0 auto;
}

.footer p {
  color: #a3a3a3;
  font-size: 0.875rem;
}

/* Mobile */
@media (max-width: 768px) {
  .nav-links {
    gap: 20px;
  }

  .hero {
    padding: 80px 16px 64px;
  }

  .section {
    padding: 64px 16px;
  }

  .section-cta {
    padding: 64px 16px;
  }

  .card-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .nav-links {
    gap: 12px;
  }

  .nav-links a {
    font-size: 0.8125rem;
  }

  .card {
    padding: 24px;
  }
}
